/* ===== module: app-updates.js ===== */
    /** In-app update checks (user 2026-09-11). iOS home-screen PWAs resumed
        from the app switcher fire no navigation, so the browser can go days
        without discovering a new service worker. We poll explicitly instead:
        a manual "Check for updates" button in Settings → About, plus a quiet
        auto-check whenever the app is foregrounded. Never force-reloads — the
        user confirms, and a live workout draft always defers the prompt. */
        /* Module map (v1.006) — Key: armUpdateWatch(), maybeAutoUpdateCheck(), offerUpdateRefresh(), waitForWorkerState(). FORK v1.991.15 (FR-63): + probeServerVersion()/versionIsNewer() (server truth), aboutUpdateAvailableText()/renderAboutUpdateLine() (About's running-vs-available labels), applyPendingUpdate() (the whole-build swap). Depends on: navigator.serviceWorker only; no app-module deps. */

    const AUTO_UPDATE_CHECK_MS = 10 * 60 * 1000;
    const UPDATE_ACTIVATION_TIMEOUT_MS = 20000;
    let lastAutoUpdateCheck = 0;
    let pendingUpdateWorker = null;
    let dismissedUpdateWorker = null;
    /* #99 A18: a fast worker could already be `active` (and claimed) by the
       time a check looked at reg.installing/reg.waiting — both empty, and
       the check wrongly reported "latest". We retain the installing worker
       through its lifecycle via updatefound, and treat a mid-session
       controller flip as an update (this page still runs the old code).
       FORK v1.991.70 (R10 item 14): the generated SW no longer
       skipWaiting()s on install, so the normal case is now a worker
       parked in `waiting` until the user accepts; the tracked worker
       and the controller-flip path remain for the cases that still
       activate without this page's acceptance (another tab's
       acceptance, a worker that was already active). */
    let trackedUpdateWorker = null;
    /* FORK v1.983 (D11): the SW byte-compare was the ONLY update signal,
       and build-info.js is precached cache-first — a profile could sit
       stranded on an old build while Settings insisted "You're on the
       latest version" (observed live: a v1.977 profile, server several
       versions ahead, no prompt, truthful-looking toast). The check now
       ALSO probes the server's build-info.js directly, bypassing both
       caches: the cache-busting query defeats the SW cache match
       (requests are keyed by full URL) and cache:'no-store' defeats the
       HTTP cache. When the server is newer but no worker activates (the
       stranded case), the offer's Refresh takes a recovery path —
       unregister the SW, then reload — so the fresh build loads over the
       network and a fresh SW installs. */
    let serverUpdatePending = false;
    let lastProbedServerVersion = null;
    let dismissedServerVersion = null;
    /* Fetches the server's advertised version, or null when the probe
       fails (offline, parse miss). Failure is silent: the SW flow below
       remains the fallback signal, exactly as before this probe existed. */
    async function probeServerVersion() {
      try {
        const res = await fetch('assets/js/build-info.js?cg-update-probe=' + Date.now(), { cache: 'no-store' });
        if (!res || !res.ok) return null;
        const text = await res.text();
        const m = /appVersion\s*:\s*"(\d+(?:\.\d+)*)"/.exec(text || '');
        return m ? m[1] : null;
      } catch (_) { return null; }
    }
    /* Numeric-tuple version compare ("1.982" > "1.98" > "1.9"). */
    function versionIsNewer(serverVersion, runningVersion) {
      const a = String(serverVersion || '').split('.').map((n) => parseInt(n, 10));
      const b = String(runningVersion || '').split('.').map((n) => parseInt(n, 10));
      if (a.some(Number.isNaN) || b.some(Number.isNaN)) return false;
      for (let i = 0; i < Math.max(a.length, b.length); i++) {
        const d = (a[i] || 0) - (b[i] || 0);
        if (d > 0) return true;
        if (d < 0) return false;
      }
      return false;
    }
    /* FORK v1.991.15 (FR-63): About's update-line text. The RUNNING
       version is window.BUILD_INFO — the boot bundle's own stamp, which
       the SW now serves cache-first with the rest of the shell, so it
       always names the build this page is actually running. A fetched
       server version is only ever labeled an AVAILABLE update, here,
       never the current version. Pure so tests can exercise it. */
    function aboutUpdateAvailableText(runningVersion, serverVersion) {
      if (!serverVersion || !runningVersion) return null;
      return versionIsNewer(serverVersion, runningVersion) ? ('Update available: v' + serverVersion) : null;
    }
    /* Shows/hides About's "Update available" line from the checker's
       verified state: a probed newer server build (named), or a pending
       worker offer whose version the probe hasn't named yet (unnamed).
       Hidden whenever the latest probe says this build is current. The
       line deliberately survives the dialog's "Later" — the dialog is
       the interruption; the line is the standing, honest label. */
    function renderAboutUpdateLine() {
      const line = $('#updateAvailableLine');
      if (!line) return;
      const runningVersion = (typeof window !== 'undefined' && window.BUILD_INFO) ? window.BUILD_INFO.appVersion : null;
      let text = aboutUpdateAvailableText(runningVersion, lastProbedServerVersion);
      if (!text && (pendingUpdateWorker || serverUpdatePending)) text = 'Update available';
      if (text) {
        const span = $('#updateAvailableText');
        if (span) span.textContent = text;
      }
      line.hidden = !text;
    }
    const swApi = ('serviceWorker' in navigator) ? navigator.serviceWorker : null;
    const initialSWController = swApi ? swApi.controller : null;
    /* True when a workout draft is currently in progress. */
    function draftIsLive() {
      return typeof workoutState !== 'undefined' && !!workoutState.draft;
    }
    /* #351 (user 2026-09-14): stash the workout-tab sub-screen before an
       update reload so boot can put the user back where they were. Only the
       workout tab has update-interruptible sub-screens worth restoring (live
       editor via a manual check mid-draft, builder, saved-workout detail,
       log list) — everything else is a tap away. sessionStorage dies with
       the tab, so a stale stash can never resurrect in a later session. */
    function stashRouteForUpdateReload(){
      try{
        if(typeof state==='undefined')return;
        sessionStorage.setItem('cg-post-update-route',JSON.stringify({
          view:state.activeView||null,
          workoutEditorOpen:!!(state.workoutEditorOpen&&typeof workoutState!=='undefined'&&workoutState.draft),
          builderOpen:!!(state.builderOpen&&state.savedBuilder),
          savedWorkoutId:state.savedWorkoutId||null,
          workoutHistoryOpen:!!state.workoutHistoryOpen,
        }));
      }catch(_){}
    }
    /* #351 (user 2026-09-14): after an update reload, restore the workout-tab
       sub-screen stashed above. Consumed once; a saved workout that no
       longer exists is dropped rather than resurrected. Named (not inline
       in app-bootstrap.js) so the stash/restore round-trip is unit-testable. */
    function restoreRouteAfterUpdateReload(bootShareAttempt){
      try{
        const rawRoute=sessionStorage.getItem('cg-post-update-route');
        sessionStorage.removeItem('cg-post-update-route');
        const savedRoute=rawRoute?JSON.parse(rawRoute):null;
        if(savedRoute&&!bootShareAttempt&&savedRoute.view==='workout'){
          if(savedRoute.savedWorkoutId&&!workoutState.templates.some(t=>t.id===savedRoute.savedWorkoutId))savedRoute.savedWorkoutId=null;
          if(savedRoute.workoutEditorOpen||savedRoute.builderOpen||savedRoute.savedWorkoutId||savedRoute.workoutHistoryOpen){
            state.workoutEditorOpen=!!savedRoute.workoutEditorOpen;
            state.builderOpen=!!savedRoute.builderOpen;
            state.savedWorkoutId=savedRoute.savedWorkoutId;
            state.workoutHistoryOpen=!!savedRoute.workoutHistoryOpen;
            showWorkouts(false,true);
          }
        }
      }catch(_){}
    }
    /* Shows the update prompt (deferred while a draft is live, deduped against snoozed workers). */
    function offerUpdateRefresh(worker) {
      if (worker) pendingUpdateWorker = worker;
      renderAboutUpdateLine(); /* FORK v1.991.15 (FR-63): About labels the available update even when the dialog itself is deferred or snoozed. */
      if (dismissedUpdateWorker && worker && dismissedUpdateWorker === worker) return; /* snoozed with "Later" */
      if (draftIsLive()) return; /* a live workout is never interrupted — the offer surfaces on a later check */
      const dlg = $('#updateAvailableDialog');
      if (dlg && !dlg.open) dlg.showModal();
    }
    /* Retains the installing worker through its lifecycle so an activation surfaces an offer. */
    function armUpdateWatch(reg) {
      if (!reg || reg._cgUpdateWatchArmed) return;
      reg._cgUpdateWatchArmed = true;
      reg.addEventListener('updatefound', () => {
        const worker = reg.installing;
        if (!worker) return;
        trackedUpdateWorker = worker; /* retain through the lifecycle */
        worker.addEventListener('statechange', () => {
          /* FORK v1.991.70 (R10 item 14): an update is offered when the
             new worker is INSTALLED (waiting), not after it activates —
             the generated SW no longer skipWaiting()s on install, so
             activation is the user's decision (Refresh now sends
             SKIP_WAITING; "Later" leaves the worker waiting and a plain
             reload keeps serving the running build). A first install
             (no controller when the page booted) is not an update and
             never offers. The 'activated' offer stays for a worker
             that activates without this page accepting (another tab
             accepted, or every other client closed) — offerUpdateRefresh
             itself dedupes against a snoozed worker. */
          if (worker.state === 'installed' && initialSWController) offerUpdateRefresh(worker);
          else if (worker.state === 'activated' && initialSWController) offerUpdateRefresh(worker);
          else if (worker.state === 'redundant' && trackedUpdateWorker === worker) trackedUpdateWorker = null;
        });
      });
    }
    if (swApi) {
      /* A new controller mid-session means an update activated and claimed
         this page (skipWaiting + clients.claim in the SW). The initial claim
         on first install runs the code this page already loaded — not an update. */
      swApi.addEventListener('controllerchange', () => {
        const c = swApi.controller;
        if (initialSWController && c && c !== initialSWController) offerUpdateRefresh(c);
      });
    }

    /** Resolve with the worker's state once it reaches `target` (or goes
        redundant), or with its current state on timeout. */
    function waitForWorkerState(worker, target, timeoutMs) {
      return new Promise((resolve) => {
        if (!worker || worker.state === target || worker.state === 'redundant') {
          resolve(worker ? worker.state : 'none');
          return;
        }
        const timer = setTimeout(() => {
          worker.removeEventListener('statechange', onChange);
          resolve(worker.state);
        }, timeoutMs);
        /* Resolves when the worker reaches the target state (or goes redundant). */
        function onChange() {
          if (worker.state === target || worker.state === 'redundant') {
            clearTimeout(timer);
            worker.removeEventListener('statechange', onChange);
            resolve(worker.state);
          }
        }
        worker.addEventListener('statechange', onChange);
      });
    }

    /* Checks for a new service worker; manual checks always report the result. */
    async function checkForAppUpdate({ manual = false } = {}) {
      try {
        if (!('serviceWorker' in navigator)) {
          if (manual) showToast('Updates are handled by your browser.');
          return;
        }
        const reg = await navigator.serviceWorker.getRegistration();
        if (!reg) {
          if (manual) showToast("Couldn't check for updates. Try again in a moment.",'error');
          return;
        }
        /* Force the check now instead of waiting for the next navigation.
           The authoritative signal is reg.installing / reg.waiting — the
           browser already compared sw.js for us. */
        armUpdateWatch(reg);
        /* FORK v1.991.70 (R10 item 14): a manual check is explicit —
           it re-offers an update the dialog's "Later" snoozed. Quiet
           auto-checks keep respecting the snooze (the dismissed*
           markers below), manual ones clear it up front. */
        if (manual) { dismissedUpdateWorker = null; dismissedServerVersion = null; }
        /* FORK v1.983 (D11): probe the server version FIRST — it is the
           ground truth the SW byte-compare can fail to see. */
        const serverVersion = await probeServerVersion();
        if (serverVersion) lastProbedServerVersion = serverVersion;
        const runningVersion = (typeof window !== 'undefined' && window.BUILD_INFO) ? window.BUILD_INFO.appVersion : null;
        const serverNewer = !!(serverVersion && runningVersion && versionIsNewer(serverVersion, runningVersion));
        /* A snoozed probe-offer stays snoozed on quiet auto-checks (a
           manual check always re-offers — the user asked explicitly). */
        const serverOfferable = serverNewer && (manual || serverVersion !== dismissedServerVersion);
        const beforeController = swApi ? swApi.controller : null;
        try { await reg.update(); } catch (_) { /* offline or deploy in flight */ }
        await new Promise((r) => setTimeout(r, 0));
        /* #99 A18: a fast worker already activated (and claimed) during the
           check — reg.installing/reg.waiting are empty, but the controller
           flip proves new code is ready while this page still runs old code. */
        const afterController = swApi ? swApi.controller : null;
        if (beforeController && afterController && afterController !== beforeController) {
          serverUpdatePending = false; /* a real worker claimed the page — the normal Refresh path applies */
          offerUpdateRefresh(afterController);
          return;
        }
        const worker = reg.installing || reg.waiting ||
          ((trackedUpdateWorker && trackedUpdateWorker.state !== 'redundant' && trackedUpdateWorker.state !== 'activated') ? trackedUpdateWorker : null);
        if (!worker) {
          /* An offer deferred earlier (live draft) still surfaces on a later
             check once the draft is gone. */
          if (pendingUpdateWorker && !draftIsLive()) { offerUpdateRefresh(pendingUpdateWorker); return; }
          /* FORK v1.983 (D11): no worker, but the server probe says a
             newer build exists — the stranded-profile case. Offer the
             dialog; its Refresh takes the unregister-and-reload recovery
             path (see serverUpdatePending in the Refresh handler). */
          if (serverOfferable) { serverUpdatePending = true; offerUpdateRefresh(null); return; }
          /* FORK v1.991.15 (FR-63): a completed probe that found nothing
             newer clears any stale About update line. (A failed probe —
             serverVersion null — leaves the line as it was: unverified
             is not the same as up to date.) */
          if (serverVersion) renderAboutUpdateLine();
          if (manual) showToast("You're on the latest version.");
          return;
        }
        /* FORK v1.991.70 (R10 item 14): the offer state is WAITING
           ('installed' while an older worker controls this page), not
           'activated' — the new worker must not activate until the
           user accepts, and Refresh (applyPendingUpdate) performs the
           activation via SKIP_WAITING. (Pre-fix this waited for
           'activated', which the old install-time skipWaiting made
           immediate — and which is exactly why "Later" could not
           defer: by the time the dialog showed, the new worker had
           already taken over and deleted the old cache.) A first
           install (no controller) still runs to 'activated': that
           build simply becomes current, no offer needed. */
        const state = (worker.state === 'installed' || worker.state === 'activated')
          ? worker.state
          : await waitForWorkerState(worker, beforeController ? 'installed' : 'activated', UPDATE_ACTIVATION_TIMEOUT_MS);
        if (state !== 'installed' && state !== 'activated') {
          /* FORK v1.983 (D11): a worker exists but won't activate while
             the server is verifiably newer — offer the recovery Refresh
             rather than a "try again" toast that loops forever. */
          if (serverOfferable) { serverUpdatePending = true; offerUpdateRefresh(worker); return; }
          if (manual) showToast(state === 'redundant'
            ? "Update found but couldn't download. Try again."
            : 'Still downloading the update. Try again in a moment.');
          return;
        }
        if (state === 'activated' && !beforeController) {
          /* First install reaching activated: it is the current
             build now, not an update to offer. */
          if (manual) showToast("You're on the latest version.");
          return;
        }
        serverUpdatePending = false;
        offerUpdateRefresh(worker);
        return;
      } catch (_) {
        if (manual) showToast("Couldn't check for updates. You're offline?",'error');
      }
    }

    /* Quiet foreground update check, throttled to every 10 minutes, never during a live draft. */
    function maybeAutoUpdateCheck() {
      /* FORK v1.991.70 (R10 item 14): the workout gate runs BEFORE the
         throttle stamp. A live workout is never interrupted — neither
         by the check's dialog (offerUpdateRefresh also refuses while
         a draft is live) nor by burning the 10-minute throttle, so
         the first foreground/focus/online event AFTER the workout
         ends runs the check immediately and a deferred offer surfaces
         then. That post-workout check is the pinned surfacing point
         for an update detected mid-workout. Manual checks always
         show immediately. */
      if (typeof workoutState !== 'undefined' && workoutState.draft) return;
      const now = Date.now();
      if (now - lastAutoUpdateCheck < AUTO_UPDATE_CHECK_MS) return;
      lastAutoUpdateCheck = now;
      checkForAppUpdate({ manual: false });
    }

    $('#checkUpdatesButton')?.addEventListener('click', () => checkForAppUpdate({ manual: true }));
    /* FORK v1.991.15 (FR-63): accepting an update swaps the WHOLE build —
       version and assets move together, never separately. Shared by the
       dialog's Refresh now and About's update line. Paths:
       - Recovery (D11): the offer came from the server probe, not from
         an activated worker, so a plain reload would just re-serve the
         stranded build from the old SW's cache. Unregister first: the
         reload then loads fresh over the network and a fresh SW
         installs.
       - Waiting worker: ask it to activate (SKIP_WAITING) and reload
         when it takes control (controllerchange), timeout falling back
         to a plain reload. Loop guard: if a SKIP_WAITING reload was
         already attempted in the last minute and a worker is STILL
         waiting, the chain is not converging — escalate to the
         unregister recovery rather than reload in circles.
       - Otherwise the new worker has already activated and claimed the
         page (skipWaiting in install, clients.claim in activate), so a
         plain reload serves the new build whole. */
    const UPDATE_WAITING_RELOAD_KEY = 'cg-waiting-reload-at';
    async function applyPendingUpdate() {
      $('#updateAvailableDialog')?.close();
      stashRouteForUpdateReload(); /* #351 */
      if (serverUpdatePending) {
        serverUpdatePending = false;
        try {
          const reg = await navigator.serviceWorker.getRegistration();
          if (reg) await reg.unregister();
        } catch (_) { /* reload regardless */ }
        location.reload();
        return;
      }
      try {
        const reg = await navigator.serviceWorker.getRegistration();
        const waiting = reg ? (reg.waiting ||
          ((pendingUpdateWorker && pendingUpdateWorker.state === 'installed') ? pendingUpdateWorker : null)) : null;
        if (waiting && swApi) {
          let lastAttempt = 0;
          try { lastAttempt = Number(sessionStorage.getItem(UPDATE_WAITING_RELOAD_KEY) || 0); } catch (_) {}
          if (lastAttempt && (Date.now() - lastAttempt) < 60000) {
            try { sessionStorage.removeItem(UPDATE_WAITING_RELOAD_KEY); } catch (_) {}
            try { await reg.unregister(); } catch (_) { /* reload regardless */ }
            location.reload();
            return;
          }
          try { sessionStorage.setItem(UPDATE_WAITING_RELOAD_KEY, String(Date.now())); } catch (_) {}
          await new Promise((resolve) => {
            let settled = false;
            const finish = () => { if (!settled) { settled = true; resolve(); } };
            const onControllerChange = () => { swApi.removeEventListener('controllerchange', onControllerChange); finish(); };
            swApi.addEventListener('controllerchange', onControllerChange);
            setTimeout(finish, 3000);
            try { waiting.postMessage({ type: 'SKIP_WAITING' }); } catch (_) { finish(); }
          });
        }
      } catch (_) { /* reload regardless */ }
      location.reload();
    }
    $('#updateRefreshNow')?.addEventListener('click', () => { applyPendingUpdate(); });
    $('#aboutUpdateRefresh')?.addEventListener('click', () => { applyPendingUpdate(); });
    /* FORK v1.991.70 (R10 item 14): "Later" DEFERS — it never applies.
       The pending worker stays WAITING (no SKIP_WAITING is sent and
       the running build's cache is untouched), so a plain reload
       keeps serving the running build; the update applies only on
       explicit acceptance — Refresh now here, or later from
       Settings → About's update line, whose applyPendingUpdate finds
       the waiting worker (or takes the D11 recovery for a
       probe-offered update). pendingUpdateWorker / serverUpdatePending
       are therefore KEPT, not cleared: renderAboutUpdateLine and
       applyPendingUpdate both read them. Only the dialog is snoozed:
       the dismissed* markers stop quiet auto-checks re-opening it for
       this same update (a manual Check for updates clears them and
       re-offers — see checkForAppUpdate). */
    $('#updateLater')?.addEventListener('click', () => {
      dismissedUpdateWorker = pendingUpdateWorker;
      if (serverUpdatePending) { dismissedServerVersion = lastProbedServerVersion; }
      $('#updateAvailableDialog')?.close();
    });
    $('#closeUpdateAvailable')?.addEventListener('click', () => {
      dismissedUpdateWorker = pendingUpdateWorker;
      if (serverUpdatePending) { dismissedServerVersion = lastProbedServerVersion; }
      $('#updateAvailableDialog')?.close();
    });
    /* #414: the future-version boot prompt (persistence.js holdForFutureVersion).
       "Reload now" pulls the new worker — skipWaiting()+clients.claim() in
       sw.js mean the reloaded page runs the new build, which reads the
       untouched blob normally. "Not now"/× just dismisses; the persist hold
       stays in place, so nothing is saved until a real reload. */
    $('#futureVersionReload')?.addEventListener('click', () => {
      $('#futureVersionDialog')?.close();
      stashRouteForUpdateReload(); /* #351 */
      location.reload();
    });
    $('#futureVersionLater')?.addEventListener('click', () => {
      $('#futureVersionDialog')?.close();
    });
    $('#closeFutureVersion')?.addEventListener('click', () => {
      $('#futureVersionDialog')?.close();
    });

    document.addEventListener('visibilitychange', () => { if (!document.hidden) maybeAutoUpdateCheck(); });
    window.addEventListener('focus', () => maybeAutoUpdateCheck());
    window.addEventListener('online', () => maybeAutoUpdateCheck());
    window.addEventListener('load', () => setTimeout(maybeAutoUpdateCheck, 5000));
